INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('nature', 'mage', 'mage', 'Mage', NULL, '{"nature":"mage","description":"Un Mage est un Humain lié à un Mageius, structure magique quasi autonome qui lui permet d’imposer sa volonté au réel. Sa magie n’est pas une liste fermée de sorts : elle dépend d’Affinités, de Maîtrise, d’Amplitude et surtout de ce que le personnage comprend réellement du phénomène qu’il veut modifier. Il peut improviser dans une Affinité non éveillée en Maîtrise Initiale / Amplitude Mineure avec +1 niveau de difficulté ; les rangs supérieurs exigent son éveil. Le Mageius peut aussi porter des Échos de porteurs plus anciens sans remplacer l’identité actuelle du Mage.","carte":"**MAGE · NATURE**\n\n- **Voilé** : humain ordinaire. Le Mageius ne lance aucun sort.\n- **Semi-Révélé** : +1 Esprit, +1 Volonté. Vision à travers le Voile, Perception magique, Protection du Mageius. Amplitude maximale : Mineure.\n- **Révélé** : +1 Esprit, +2 Volonté (remplace le SR). Toutes tes Affinités, Maîtrises et Amplitudes. Ton apparence peut rester humaine.\n\n**Traits gratuits**\n\n- **Type de Mageius** : Kaharal, Meldir, Elinaeth, Mestherak ou Discella. Il fixe tes trois Affinités natives et ta place sur la Roue.\n- **Affinité dominante** : une Affinité native de ton Type, gratuite en Maîtrise Initiale / Amplitude Mineure. *Résonance dominante* : 1/scène, relance le d10e d''un sort de cette Affinité et garde le second résultat.\n- **Vision à travers le Voile** (SR/R) : tu vois ce que voit un observateur de ton niveau de Révélation.\n- **Perception magique** (SR/R) : tu sens nœuds, enchantements, traces et présences magiques. Esprit + Perception si c''est incertain. Ni leur Nature, ni leur histoire, ni leur fonctionnement exact.\n- **Protection du Mageius** (SR/R) : +3 à la Défense occulte contre les effets surnaturels qui agissent directement sur toi. Rien contre une conséquence devenue physique. Disparaît en Dormance.\n- **Canalisation** (SR/R) : échanger du temps contre de la fiabilité, sans talent (voir le moteur).\n- **Volonté supérieure** : avant un sort, monter d''un palier ta Maîtrise, ton Amplitude ou les deux. Après le sort, réussi ou non : Revers catastrophique automatique.\n\n**Faiblesse : la Tension du Mageius.** Chaque sort la fait monter. À 3 ou plus, test de Revers (Volonté + Force Mentale). Un Revers coûte 3, 5 ou 7 PV irréductibles et endort le Mageius (Dormance, 2 à 5 jours) : plus de sorts, plus de Protection, plus de Perception magique.\n\n**Changements** : les 15 traits « Affinité dominante — X » (texte identique) deviennent un trait unique, lié au Type de Mageius, qui n''apparaissait sur aucun trait. Le trait disait « un test utilisant cette Affinité », la règle dit « un sort » : la carte retient « un sort ».","traits_gratuits":[{"name":"Vision à travers le Voile","access":"SR/R","effect":"Perçoit les créatures et phénomènes accessibles à son niveau de Révélation."},{"name":"Perception magique","access":"SR/R","effect":"Ressent nœuds, enchantements, traces et présences magiques."},{"name":"Protection du Mageius","access":"SR/R","effect":"+3 Défense occulte contre les effets surnaturels agissant directement sur le Mage."}],"droits_acquis":"Les talents achetés avant les voies restent acquis ; les règles de voie valent pour les achats suivants (décision 20)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'mage', 'mage_voies', 'Voies', NULL, '{"nature":"mage","chemin":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'mage', 'mage_discipline_du_conduit', 'Discipline du conduit', NULL, '{"nature":"mage","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":"  - *Décharge* : 1 PA, 1/round, Volonté + Maîtrise spirituelle contre 15. Réussite : −1 Tension. Échec narratif : +1 Tension.\n  - *Ancrage* : +3 pour garder la concentration d''un sort préparé ou maintenu malgré une perturbation sérieuse, et +3 contre un effet qui veut sceller, corrompre, arracher ou déplacer ton Mageius.\n  - *Référence* : aucun des deux n''annule un Revers déjà déclenché ni ne raccourcit la Dormance. La Décharge ne compte pas comme un round de repos. L''Ancrage ne s''applique jamais au test de Revers et ne se cumule pas avec une protection équivalente.","changements":"Décharge contrôlée et Ancrage du Mageius fusionnés au palier II **à coût constant** (1 + 1 = 2 PTV, comme Prédateur II du Vampire). Ordre imposé : Équilibrage d''abord ; un Mage qui ne voulait que l''Ancrage paie donc 3 PTV au lieu de 1. Chiffres inchangés ; le jet de la Décharge est gardé."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'capacites_et_talents_communs_talents_communs_equilibrage_du_flux', 'Équilibrage du Flux', NULL, '{"nature":"mage","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Passif · premier changement du round","texte_court":"la première fois par round que tu changes d''Affinité en lançant vraiment un sort, ta Tension baisse de 2 au lieu de 1 (minimum 0), avant d''ajouter celle du nouveau sort.","texte_reference":"La première fois par round que vous changez d’Affinité, réduisez votre Tension de 2 au lieu de 1, minimum zéro, avant d’ajouter la Tension du nouveau sort. Il faut réellement lancer le nouveau sort : changer seulement un choix ou un nom ne décharge rien et n’annule pas un Revers déjà déclenché.","lore":"Changer d’Affinité n’est plus une rupture brutale. Le Mage laisse le premier courant se vider proprement avant d’en accueillir un autre, comme un musicien qui sait faire mourir une note avant d’attaquer la suivante.","groupe_actuel":"Capacités et Talents communs › Talents communs","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'capacites_et_talents_communs_talents_communs_decharge_controlee', 'Tenir le conduit', NULL, '{"nature":"mage","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"1 PA · 1/round","texte_court":"tu gagnes deux usages.","texte_reference":"Une fois par round, 1 PA et Volonté + Maîtrise spirituelle + 1d10e contre 15 : réussite, −1 Tension (minimum zéro) ; échec ordinaire, aucun changement ; échec narratif, +1 Tension. La Décharge utilise le Mageius, ne compte pas comme un round de repos et n’annule pas rétroactivement un Revers ou la Dormance.\nSR/R : +3 aux tests pour conserver la concentration d’un sort en préparation ou maintenu malgré une perturbation significative ; +3 pour résister aux effets visant spécifiquement à sceller, corrompre, arracher, déplacer ou désolidariser le Mageius. Une seule application sur un même jet, sans cumul avec une Protection innée ou équivalente déjà applicable. Aucun bonus aux tests de Revers, aucune réduction de Dormance, aucun PA de maintien offert et aucun bonus permanent de Compétence.","lore":"Le Mage apprend à ouvrir une issue avant que la pression accumulée n’explose d’elle-même. La magie excédentaire s’évacue par un geste, un souffle ou un signe maîtrisé, au prix d’un bref effort de concentration.","groupe_actuel":"Capacités et Talents communs › Talents communs","statut_regle":"correction","changements":"Fusion de Décharge contrôlée et Ancrage du Mageius."}'::jsonb, 'published', ARRAY['capacites_et_talents_communs_talents_communs_ancrage_du_mageius']::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'mage', 'mage_genealogie_d_idees', 'Généalogie d''idées', NULL, '{"nature":"mage","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":"  - *Écho du Mageius* (SR/R) : un sort précis laissé par un ancien porteur, défini avec le MJ après une découverte sur l''histoire de ton Mageius. Pour cet effet exact, −1 niveau de Difficulté (minimum 12), sans baisser Défense, PA ni Tension. Sans l''Affinité, tu le lances en Initiale / Mineure ; une fois l''Affinité apprise, il suit ta Maîtrise et ton Amplitude.\n  - *Magie familiale* (R) : un sort de famille ou de Loge qu''on t''a réellement enseigné. Tu dois posséder chacune de ses Affinités, Maîtrises et Amplitudes requises ; une Affinité étrangère s''ouvre toujours par la Roue, sauf exception de la tradition accordée par le MJ.\n  - L''autre origine peut s''ajouter plus tard, pour 2 PTV.","changements":"Résonance héritée et Héritage familial deviennent les deux variantes du palier II, coût inchangé (2 PTV chacune). **Nouveau prérequis** : l''Œuvre personnelle demande un Sort reçu, en plus de ses prérequis du moteur (+2 PTV sur un total d''environ 12). Voir question 1. Phrases destinées au Builder retirées (« le formulaire ne vaut jamais autorisation MJ », etc.). Une seule règle, en tête des voies : *tout ce qui se définit avec le MJ (Écho, Magie familiale, Œuvre) se fixe avant l''achat ; la fiche ne vaut pas accord du MJ.*"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'capacites_et_talents_communs_talents_communs_resonance_heritee', 'Résonance héritée', NULL, '{"nature":"mage","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":"Selon l’Écho défini","texte_court":"choisis son origine. (Résonance héritée)","texte_reference":"Définissez avant achat l’Écho d’un ancien porteur et ses paramètres avec le MJ. Pour cet effet exact, −1 niveau de Difficulté intrinsèque, minimum 12 ; aucune réduction de la Défense adverse, des PA ou de la Tension. Sans Affinité éveillée, seul cet Écho est disponible en Initiale / Mineure ; une fois l’Affinité apprise, il suit vos propres Maîtrise et Amplitude. L’Écho n’éveille pas toute l’Affinité. La fiche descriptive ne constitue pas une approbation du MJ.","lore":"Le Mageius conserve parfois des empreintes laissées par ceux qui l’ont porté avant cette incarnation. En apprenant à écouter cette mémoire étrangère, le Mage peut réveiller un Écho sans le confondre avec ses propres souvenirs.","groupe_actuel":"Capacités et Talents communs › Talents communs","statut_regle":"correction","changements":"Résonance héritée et Héritage familial deviennent les deux variantes du palier II, coût inchangé (2 PTV chacune). **Nouveau prérequis** : l''Œuvre personnelle demande un Sort reçu, en plus de ses prérequis du moteur (+2 PTV sur un total d''environ 12). Voir question 1. Phrases destinées au Builder retirées (« le formulaire ne vaut jamais autorisation MJ », etc.). Une seule règle, en tête des voies : *tout ce qui se définit avec le MJ (Écho, Magie familiale, Œuvre) se fixe avant l''achat ; la fiche ne vaut pas accord du MJ.*"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'capacites_et_talents_communs_talents_communs_heritage_familial', 'Héritage familial', NULL, '{"nature":"mage","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":"Selon la technique transmise","texte_court":"choisis son origine. (Héritage familial)","texte_reference":"Une technique familiale identifiée doit avoir été réellement enseignée et définie avec le MJ. Vérifiez chacune de ses Affinités, Maîtrises et Amplitudes requises, pas une progression quelconque dans un autre domaine. L’achat coûte 2 PTV et n’exige pas d’acheter Œuvre personnelle en plus ; une Affinité étrangère reste à ouvrir par la Roue sauf exception explicitement accordée par la tradition et le MJ. Le formulaire ne vaut jamais autorisation MJ.","lore":"Certaines familles ont transmis des pratiques assez longtemps pour qu’elles deviennent plus qu’un style personnel. Le Mage reçoit cette tradition comme on reçoit une langue ancienne : avec ses gestes, ses interdits et ses raccourcis propres.","groupe_actuel":"Capacités et Talents communs › Talents communs","statut_regle":"correction","changements":"Résonance héritée et Héritage familial deviennent les deux variantes du palier II, coût inchangé (2 PTV chacune). **Nouveau prérequis** : l''Œuvre personnelle demande un Sort reçu, en plus de ses prérequis du moteur (+2 PTV sur un total d''environ 12). Voir question 1. Phrases destinées au Builder retirées (« le formulaire ne vaut jamais autorisation MJ », etc.). Une seule règle, en tête des voies : *tout ce qui se définit avec le MJ (Écho, Magie familiale, Œuvre) se fixe avant l''achat ; la fiche ne vaut pas accord du MJ.*"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'capacites_et_talents_communs_talents_communs_uvre_personnelle', 'Œuvre personnelle', NULL, '{"nature":"mage","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R","activation":"Selon l’Œuvre définie","texte_court":"il faut Maîtrise Magistrale et Amplitude Majeure dans ton Affinité principale. Avec le MJ, tu inventes un sort signature qui enfreint une règle générale de la magie, sur une idée forte : une portée impossible, une autre Défense, deux domaines fusionnés, une permanence. Jamais « tous mes sorts sont meilleurs ». Vous fixez ensemble effet, Affinités, Maîtrise, Amplitude, PA, portée, Tension et exception.","texte_reference":"Prérequis : Maîtrise Magistrale et Amplitude Majeure dans l’Affinité principale, avec développement narratif approprié. L’Œuvre est définie avec le MJ : effet, Affinités requises, Maîtrise, Amplitude, PA, portée, Tension et exception propre. Elle doit ouvrir une possibilité distincte de l’improvisation ordinaire ; elle n’améliore pas tous vos sorts. L’achat coûte 3 PTV, en plus des paliers ; aucune exception ou autorisation MJ n’est créée par un texte saisi par le joueur.","lore":"À ce niveau, la magie porte une signature qu’aucun manuel ne pouvait fournir. Des années de pratique, d’erreurs et de compréhension produisent une technique qui n’existe réellement que parce que ce Mage-là l’a pensée.","groupe_actuel":"Capacités et Talents communs › Talents communs","statut_regle":"correction","changements":"Résonance héritée et Héritage familial deviennent les deux variantes du palier II, coût inchangé (2 PTV chacune). **Nouveau prérequis** : l''Œuvre personnelle demande un Sort reçu, en plus de ses prérequis du moteur (+2 PTV sur un total d''environ 12). Voir question 1. Phrases destinées au Builder retirées (« le formulaire ne vaut jamais autorisation MJ », etc.). Une seule règle, en tête des voies : *tout ce qui se définit avec le MJ (Écho, Magie familiale, Œuvre) se fixe avant l''achat ; la fiche ne vaut pas accord du MJ.*"}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'progression_par_points_de_verite_maitrise_affinee', 'Affinée', NULL, '{"nature":"mage","cout":1,"cout_actuel":1,"palier":null,"porte":null,"hors_voie":true,"acces":"—","activation":"Progression permanente · par Affinité","texte_court":"Vous façonnez des effets précis et des formes complexes, et pouvez diviser simplement une même manifestation. Ce palier améliore la finesse du sort, pas son échelle.","texte_reference":"Maîtrise Affinée — 1 PTV, après Initiale dans cette Affinité. Précision élevée, formes complexes et division simple d’un effet ; les possibilités exactes dépendent de l’Affinité, l’Amplitude autorise son échelle et une fonction distincte doit être justifiée.","lore":"La magie devient précise plutôt que simplement plus forte. Formes complexes, contours choisis et divisions simples apparaissent parce que le Mage commence à comprendre où son Affinité peut être sculptée sans perdre sa cohérence.","groupe_actuel":"Progression par Points de Vérité › Maîtrise","statut_regle":"origine","changements":"Laissé hors des voies par le lot (moteur, maîtrise ou rang)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'progression_par_points_de_verite_maitrise_superieure', 'Supérieure', NULL, '{"nature":"mage","cout":2,"cout_actuel":2,"palier":null,"porte":null,"hors_voie":true,"acces":"—","activation":"Progression permanente · par Affinité","texte_court":"Vous combinez plusieurs paramètres dans un même sort et lui donnez des comportements élaborés ou indirects. L’Amplitude doit toujours permettre l’échelle choisie.","texte_reference":"Maîtrise Supérieure — 2 PTV après Affinée, soit 3 PTV cumulés depuis Initiale. Plusieurs paramètres simultanés, effets indirects et comportements élaborés deviennent possibles selon l’Affinité ; ce palier ouvre aussi l’accès à un Accord adjacent.","lore":"Plusieurs paramètres peuvent désormais rester présents dans le même raisonnement magique. L’effet devient capable de réagir, de contourner ou de combiner des comportements sans que le Mage perde le fil de ce qu’il impose au réel.","groupe_actuel":"Progression par Points de Vérité › Maîtrise","statut_regle":"origine","changements":"Laissé hors des voies par le lot (moteur, maîtrise ou rang)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'progression_par_points_de_verite_maitrise_magistrale', 'Magistrale', NULL, '{"nature":"mage","cout":3,"cout_actuel":3,"palier":null,"porte":null,"hors_voie":true,"acces":"—","activation":"Progression permanente · par Affinité","texte_court":"Vous poussez le concept de votre Affinité jusqu’à ses applications les plus complexes. Avec l’Amplitude Majeure et le développement narratif requis, vous pouvez acheter une Œuvre personnelle.","texte_reference":"Maîtrise Magistrale — 3 PTV après Supérieure, soit 6 PTV cumulés depuis Initiale. Elle ouvre les applications extrêmes de l’Affinité mais n’accorde pas gratuitement une Œuvre personnelle, une nouvelle Affinité ou plusieurs fonctions mécaniques sans justification.","lore":"Le concept magique est assez profondément compris pour être poussé jusqu’à ses conséquences les moins évidentes. Le Mage ne se contente plus d’appliquer une Affinité : il commence à découvrir ce qu’elle permet que personne ne lui avait encore enseigné.","groupe_actuel":"Progression par Points de Vérité › Maîtrise","statut_regle":"origine","changements":"Laissé hors des voies par le lot (moteur, maîtrise ou rang)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'progression_par_points_de_verite_amplitude_significative', 'Significative', NULL, '{"nature":"mage","cout":1,"cout_actuel":1,"palier":null,"porte":null,"hors_voie":true,"acces":"—","activation":"Progression permanente · par Affinité","texte_court":"Votre magie peut agir à l’échelle d’un petit groupe, d’un véhicule ou d’une pièce. Vos effets Mineurs deviennent aussi plus faciles à lancer : −1 niveau de Difficulté intrinsèque.","texte_reference":"Amplitude Significative — 1 PTV après Mineure. Échelle d’un petit groupe, d’un véhicule ou d’une pièce ; base d’un effet Significatif : Difficulté 18, 2 PA, +2 Tension. Chaque palier d’Amplitude possédé au-dessus de l’effet lancé réduit sa Difficulté intrinsèque d’un niveau, minimum 12 ; cela ne réduit ni la Défense adverse ni les PA ou la Tension de l’effet. Avec au moins deux paliers d’avance, l’effet est automatique seulement hors opposition, urgence et difficulté réelle de contexte.","lore":"L’Affinité dépasse le geste individuel et prend assez d’ampleur pour englober une pièce, un véhicule ou plusieurs personnes. Le Mage apprend à conserver une intention cohérente lorsqu’elle s’étend au-delà d’une cible unique.","groupe_actuel":"Progression par Points de Vérité › Amplitude","statut_regle":"origine","changements":"Laissé hors des voies par le lot (moteur, maîtrise ou rang)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'progression_par_points_de_verite_amplitude_majeure', 'Majeure', NULL, '{"nature":"mage","cout":2,"cout_actuel":2,"palier":null,"porte":null,"hors_voie":true,"acces":"—","activation":"Progression permanente · par Affinité","texte_court":"Votre magie peut agir à l’échelle d’un bâtiment ou d’une grande zone. Vos effets Significatifs gagnent −1 niveau de Difficulté intrinsèque, et vos effets Mineurs −2.","texte_reference":"Amplitude Majeure — 2 PTV après Significative, soit 3 PTV cumulés depuis Mineure. Base d’un effet Majeur : Difficulté 21, 3 PA, +3 Tension. Chaque palier d’Amplitude possédé au-dessus de l’effet lancé réduit sa Difficulté intrinsèque d’un niveau, minimum 12 ; cela ne réduit ni la Défense adverse ni les PA ou la Tension de l’effet. Avec au moins deux paliers d’avance, l’effet est automatique seulement hors opposition, urgence et difficulté réelle de contexte.","lore":"Le Mage pense désormais en bâtiments, en foules et en phénomènes assez vastes pour modifier tout un lieu. La difficulté n’est plus seulement de produire l’effet, mais d’en comprendre les conséquences à cette échelle.","groupe_actuel":"Progression par Points de Vérité › Amplitude","statut_regle":"origine","changements":"Laissé hors des voies par le lot (moteur, maîtrise ou rang)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'mage', 'progression_par_points_de_verite_amplitude_cataclysmique', 'Cataclysmique', NULL, '{"nature":"mage","cout":3,"cout_actuel":3,"palier":null,"porte":null,"hors_voie":true,"acces":"—","activation":"Progression permanente · par Affinité","texte_court":"Votre magie peut transformer un quartier ou un vaste terrain. Vos effets Majeurs gagnent −1 niveau de Difficulté intrinsèque, les Significatifs −2 et les Mineurs −3, sans descendre sous 12.","texte_reference":"Amplitude Cataclysmique — 3 PTV après Majeure, soit 6 PTV cumulés depuis Mineure. Base d’un effet Cataclysmique : Difficulté 25, 4 PA, +4 Tension ; les PA peuvent être investis sur plusieurs rounds consécutifs. Chaque palier d’Amplitude possédé au-dessus de l’effet lancé réduit sa Difficulté intrinsèque d’un niveau, minimum 12 ; cela ne réduit ni la Défense adverse ni les PA ou la Tension de l’effet. Avec au moins deux paliers d’avance, l’effet est automatique seulement hors opposition, urgence et difficulté réelle de contexte.","lore":"La magie cesse de concerner une scène et commence à marquer un territoire. À cette échelle, un phénomène peut remodeler un quartier ou laisser derrière lui un événement dont témoins et archives parleront encore longtemps.","groupe_actuel":"Progression par Points de Vérité › Amplitude","statut_regle":"origine","changements":"Laissé hors des voies par le lot (moteur, maîtrise ou rang)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
