-- Généré par infrastructure/content/build-natures.mjs : ne pas modifier à la main.
-- 15 entrées, 14 relations.
BEGIN;
DELETE FROM content_relation WHERE from_id IN (SELECT id FROM content_entry WHERE scope = 'mage');
UPDATE content_entry SET status = 'archived', updated_at = now() WHERE scope = 'mage' AND status <> 'archived' AND (type, slug) NOT IN (('nature', 'mage'), ('couche', 'mage_voies'), ('voie', 'mage_discipline_du_conduit'), ('talent', 'capacites_et_talents_communs_talents_communs_equilibrage_du_flux'), ('talent', 'capacites_et_talents_communs_talents_communs_decharge_controlee'), ('voie', 'mage_genealogie_d_idees'), ('talent', 'capacites_et_talents_communs_talents_communs_resonance_heritee'), ('talent', 'capacites_et_talents_communs_talents_communs_heritage_familial'), ('talent', 'capacites_et_talents_communs_talents_communs_uvre_personnelle'), ('talent', 'progression_par_points_de_verite_maitrise_affinee'), ('talent', 'progression_par_points_de_verite_maitrise_superieure'), ('talent', 'progression_par_points_de_verite_maitrise_magistrale'), ('talent', 'progression_par_points_de_verite_amplitude_significative'), ('talent', 'progression_par_points_de_verite_amplitude_majeure'), ('talent', 'progression_par_points_de_verite_amplitude_cataclysmique'));
SELECT e.id, e.version, to_jsonb(e) - 'id', 'Import mage (voies à paliers)'
FROM content_entry e WHERE e.scope = 'mage'
ON CONFLICT (entry_id, version) DO NOTHING;
COMMIT;
